#include <stdio.h>

int main(void) {
    for (int row = 1; row <= 3; row++) {
        for (int seat = 1; seat <= 4; seat++) {
            printf("R%dS%d ", row, seat);
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    for (int i = 1; i <= 5; i++) {
        for (int j = 1; j <= 5; j++) {
            printf("%4d", i * j);
        }
        printf("\n");
    }
    return 0;
}
